<?php
require __DIR__.'/includes/bootstrap.php';require_login();$memberId=current_member_id();
if($_SERVER['REQUEST_METHOD']==='POST'){
 verify_csrf();$action=$_POST['action']??'';
 if($action==='new_list'){$name=trim($_POST['name']??'');if($name!==''){$s=$pdo->prepare('INSERT INTO family_lists(name,created_by_member_id) VALUES(?,?)');$s->execute([$name,$memberId]);log_activity($pdo,'list_added','list',(int)$pdo->lastInsertId(),$name);} }
 if($action==='add_item'){$list=(int)($_POST['list_id']??0);$name=trim($_POST['name']??'');if($list&&$name!==''){$s=$pdo->prepare('INSERT INTO family_list_items(list_id,name,quantity,created_by_member_id) VALUES(?,?,?,?)');$s->execute([$list,$name,trim($_POST['quantity']??'')?:null,$memberId]);log_activity($pdo,'list_item_added','list_item',(int)$pdo->lastInsertId(),$name); if(notifications_configured($config)){ $q=$pdo->prepare('SELECT name FROM family_lists WHERE id=?');$q->execute([$list]);$listName=(string)($q->fetchColumn()?:'Listă');$others=array_values(array_filter(array_map(fn($m)=>(int)$m['id'],family_members($pdo)),fn($id)=>$id!==$memberId)); if($others)push_send($config,$pdo,$others,member_name($pdo,$memberId).' a adăugat pe listă',$name.' · '.$listName,'/lists.php?list='.$list); }} }
 if($action==='toggle_item'){$id=(int)($_POST['id']??0);$s=$pdo->prepare('SELECT name,checked FROM family_list_items WHERE id=?');$s->execute([$id]);$r=$s->fetch();if($r){$checked=!$r['checked'];$u=$pdo->prepare('UPDATE family_list_items SET checked=?,checked_by_member_id=?,checked_at=? WHERE id=?');$u->execute([$checked?1:0,$checked?$memberId:null,$checked?date('Y-m-d H:i:s'):null,$id]);}}
 if($action==='clear_checked'){$list=(int)($_POST['list_id']??0);$pdo->prepare('DELETE FROM family_list_items WHERE list_id=? AND checked=1')->execute([$list]);}
 if($action==='delete_list'){$list=(int)($_POST['list_id']??0);if($list){$pdo->prepare('DELETE FROM family_lists WHERE id=?')->execute([$list]);log_activity($pdo,'list_deleted','list',$list,'Listă ștearsă');}header('Location:/lists.php');exit;}
 header('Location:/lists.php'.(!empty($_POST['list_id'])?'?list='.(int)$_POST['list_id']:''));exit;
}
$lists=$pdo->query("SELECT l.*,COUNT(i.id) total,SUM(i.checked=0) remaining FROM family_lists l LEFT JOIN family_list_items i ON i.list_id=l.id WHERE l.archived=0 GROUP BY l.id ORDER BY l.id")->fetchAll();
$selected=(int)($_GET['list']??($lists[0]['id']??0));$current=null;foreach($lists as $l)if((int)$l['id']===$selected)$current=$l;
$items=[];if($selected){$s=$pdo->prepare('SELECT i.*,m.name creator FROM family_list_items i LEFT JOIN family_members m ON m.id=i.created_by_member_id WHERE i.list_id=? ORDER BY i.checked,i.id DESC');$s->execute([$selected]);$items=$s->fetchAll();}
$pageTitle='Liste';$active='lists';require __DIR__.'/includes/layout_top.php';
?>
<div class="list-tabs"><?php foreach($lists as $l):?><a class="<?=$selected==(int)$l['id']?'active':''?>" href="?list=<?=$l['id']?>"><b><?=e($l['name'])?></b><span><?=max(0,(int)$l['remaining'])?> rămase</span></a><?php endforeach;?><button data-open-sheet="newListSheet"><?=icon('plus')?></button></div>
<?php if($current):?><section class="list-workspace"><div class="section-head"><div><span class="eyebrow">Listă comună</span><h2><?=e($current['name'])?></h2></div><div class="list-head-actions"><?php if($items):?><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="clear_checked"><input type="hidden" name="list_id" value="<?=$selected?>"><button class="btn ghost small">Curăță</button></form><?php endif;?><form method="post" onsubmit="return confirm('Ștergi lista și toate elementele ei?');"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="delete_list"><input type="hidden" name="list_id" value="<?=$selected?>"><button class="icon-btn tiny danger" aria-label="Șterge lista"><?=icon('trash')?></button></form></div></div><form method="post" class="quick-add-list"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="add_item"><input type="hidden" name="list_id" value="<?=$selected?>"><input name="name" required placeholder="Adaugă rapid..." autocomplete="off"><input name="quantity" placeholder="Cant." maxlength="20"><button class="btn primary" aria-label="Adaugă"><?=icon('plus')?></button></form><div class="shopping-list"><?php if(!$items):?><div class="empty">Lista e goală. Adăugați primul lucru de cumpărat.</div><?php endif;?><?php foreach($items as $i):?><form method="post" class="shopping-item <?=$i['checked']?'checked':''?>"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="toggle_item"><input type="hidden" name="list_id" value="<?=$selected?>"><input type="hidden" name="id" value="<?=$i['id']?>"><button class="check-btn"><?=$i['checked']?icon('check'):''?></button><div><strong><?=e($i['name'])?></strong><span><?=$i['quantity']?e($i['quantity']).' · ':''?>adăugat de <?=e($i['creator']?:'Sistem')?></span></div></form><?php endforeach;?></div></section><?php endif;?>
<div class="modal" id="newListSheet" aria-hidden="true"><div class="modal-backdrop" data-close-sheet></div><section class="sheet"><div class="sheet-handle"></div><div class="sheet-head"><div><span class="eyebrow">Liste</span><h2>Listă nouă</h2></div><button class="icon-btn" data-close-sheet><?=icon('close')?></button></div><form method="post" class="form-stack"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="new_list"><label>Denumire<input name="name" required placeholder="Ex: Vacanță"></label><button class="btn primary wide">Creează lista</button></form></section></div>
